/**
 *
 * CommandMenu style module.
 *
 * @module commandmenustyle
 *
 */
import type { BaseStyle, BaseStyleModule } from '@primevue/core/base/style';

export enum CommandMenuClasses {
    /**
     * Class name of root element.
     */
    root = 'p-commandmenu',
    /**
     * Class name of header element.
     */
    header = 'p-commandmenu-header',
    /**
     * Class name of list element.
     */
    list = 'p-commandmenu-list',
    /**
     * Class name of input element.
     */
    input = 'p-commandmenu-input',
    /**
     * Class name of empty message element.
     */
    emptyMessage = 'p-commandmenu-empty-message',
    /**
     * Class name of footer element.
     */
    footer = 'p-commandmenu-footer'
}

export interface CommandMenuStyle extends BaseStyle {}

declare const CommandMenuStyle: BaseStyleModule;

export default CommandMenuStyle;
